WITH r AS (SELECT * FROM bestiary_mobs FINAL WHERE capture_id NOT IN (SELECT capture_id FROM capture_trust FINAL WHERE trust = 'flagged')), g AS (SELECT groupArraySortedMapIfMerge(1)(shape_proofs) AS p FROM r), pm AS (SELECT zone_id, mob_name, sumMapIfMerge(moves) AS mv FROM r GROUP BY zone_id, mob_name), pu AS (SELECT zone_id, mob_name, id, n, hits, crits FROM pm ARRAY JOIN mv.1 AS id, mv.2 AS n, mv.3 AS hits, mv.4 AS crits WHERE n > 0 AND id = {move:UInt32}), mr AS (SELECT zone_id AS rz, mob_name AS rn, sumMapIfMerge(move_ready) AS rd FROM r GROUP BY zone_id, mob_name), mq AS (SELECT rz, rn, sum(c) AS ready_n, quantilesExactWeightedInterpolated(0.25, 0.5, 0.75)(k.2, c) AS ready_q, arraySort(groupArray([k.2, toInt64(c)])) AS ready_v FROM mr ARRAY JOIN rd.1 AS k, rd.2 AS c WHERE k.1 = {move:UInt32} GROUP BY rz, rn), zn AS (SELECT id AS zid, any(name) AS zone_name FROM zone_names GROUP BY id), ml AS (SELECT arrayMap(t -> t.2, arraySort(t -> t.1, groupArray(((-pu.n, pu.zone_id, pu.mob_name), tuple(pu.zone_id AS zone, zn.zone_name AS zone_name, pu.mob_name AS mob, pu.n AS n, pu.hits AS hits, pu.crits AS crits, mq.ready_n AS ready_n, mq.ready_q AS ready_q, mq.ready_v AS ready_v))))) AS l FROM pu LEFT JOIN zn ON zn.zid = pu.zone_id LEFT JOIN mq ON mq.rz = pu.zone_id AND mq.rn = pu.mob_name) SELECT f.*, arrayMap(k -> if(empty(g.p[f.id * 4 + k]), NULL, g.p[f.id * 4 + k][1]), [0, 1, 2, 3]) AS proofs, ml.l AS by_mob FROM tp_move_figures(move = {move:UInt32}) f CROSS JOIN g CROSS JOIN ml
